hooks.command:
bash -c 'INPUT=$(cat); FP=$(printf "%s" "$INPUT" | python3 -c "import sys,json
try:
  d=json.load(sys.stdin).get(\"tool_input\",{})
  print(d.get(\"file_path\",\"\"))
except Exception:
  print(\"\")" 2>/dev/null); case "$FP" in /etc/*|*/.ssh/*|*/.aws/*|*/.env|*/.env.production) echo "[BLOCKED by Layer 3] 受保护路径不可写: $FP" >&2; exit 2;; esac; exit 0'

bash -c 'INPUT=$(cat); CMD=$(printf "%s" "$INPUT" | python3 -c "import sys,json
try:
  print(json.load(sys.stdin).get(\"tool_input\",{}).get(\"command\",\"\"))
except Exception:
  print(\"\")" 2>/dev/null); if printf "%s" "$CMD" | grep -qE "rm[[:space:]]+-rf[[:space:]]+/|DROP[[:space:]]+(TABLE|DATABASE)|TRUNCATE[[:space:]]+TABLE|git[[:space:]]+push[[:space:]].*--force"; then echo "[BLOCKED by Layer 3] 危险命令需要人工授权: $CMD" >&2; exit 2; fi; if printf "%s" "$CMD" | grep -qE "kubectl[[:space:]]+(apply|delete|set)|helm[[:space:]]+(install|upgrade)|docker[[:space:]]+(push|stack deploy)|npm[[:space:]]+publish|pnpm[[:space:]]+publish|yarn[[:space:]]+publish|mvn[[:space:]][^;|&]*deploy|gradle[[:space:]][^;|&]*(publish|deploy)|twine[[:space:]]+upload|vercel[[:space:]].*(--prod|deploy)|netlify[[:space:]]+deploy.*--prod|wrangler[[:space:]]+(deploy|publish)|aws[[:space:]]+s3[[:space:]]+sync.*s3://|eb[[:space:]]+deploy|flyctl[[:space:]]+deploy|rails[[:space:]]+db:migrate.*RAILS_ENV=production"; then if [ -n "$RELEASE_APPROVAL" ] || printf "%s" "$CMD" | grep -qE "RELEASE_APPROVAL=[A-Za-z0-9_.-]+"; then echo "[Layer 3] 发布命令已附 RELEASE_APPROVAL 凭证，放行（production-gate 语义；凭证需可追溯到 deploy.md §4 具名人）: $CMD" >&2; else echo "[BLOCKED by Layer 3] 发布/上线命令需要具名负责人授权（Anthropic Deploy 闸门）: $CMD" >&2; echo "  授权方式（任一）：① 命令含 RELEASE_APPROVAL=<凭证> ② 会话已 export RELEASE_APPROVAL=<凭证> ③ 写进 deploy.md 由负责人签字后人工执行。" >&2; exit 2; fi; fi; exit 0'
